// Loop-closing Task 5.3 (correction 6): the UTS #39 confusable skeleton.
//
// skeleton(X), as the standard defines it: NFD; remove default-ignorable
// code points; replace each code point by its prototype from confusables.txt;
// NFD again. Two strings that look the same however they are encoded (Latin
// "A" and Cyrillic "А", "ø" and "o" + U+0338) have the same skeleton. The
// prototypes are pinned in confusables-data.ts (ICU 78.1, Unicode 17),
// generated by scripts/loop-closing/gen-confusables.py; the table holds only
// code points that NFD and NFKC leave as themselves, because identity text
// is NFKC-normalised before its skeleton is taken.

import { CONFUSABLES } from "./confusables-data.ts";

let prototypes: Map<number, string> | null = null;

function table(): Map<number, string> {
  if (prototypes === null) {
    prototypes = new Map();
    for (const entry of CONFUSABLES.split(";")) {
      const [cp, to] = entry.split(":");
      prototypes.set(parseInt(cp, 16), to.split(" ").map((h) => String.fromCodePoint(parseInt(h, 16))).join(""));
    }
  }
  return prototypes;
}

const IGNORABLE = /\p{Default_Ignorable_Code_Point}/u;

/** The UTS #39 skeleton of an NFKC-normalised string. */
export function confusableSkeleton(text: string): string {
  const map = table();
  let out = "";
  for (const ch of String(text ?? "").normalize("NFD")) {
    if (IGNORABLE.test(ch)) continue;
    out += map.get(ch.codePointAt(0)!) ?? ch;
  }
  return out.normalize("NFD");
}
